nodes.notes:
AGENT: ERP_EVENT_RECEIVER
Entry point for all ERP purchase order events.
Expects: { event_id, event_type, timestamp, purchase_order: { po_id, supplier_id, component_id, quantity, unit_price, status, promised_delivery } }

parameters.jsCode:
// ============================================================
// NORMALIZE ERP PAYLOAD → internal format
// Generates correlation_id for end-to-end tracing
// ============================================================
const raw = $json.body || $json;
const po = raw.purchase_order || raw;
const correlationId = 'CORR-ERP-' + Date.now();

return [{ json: {
  correlation_id: correlationId,
  event_id: raw.event_id || 'EVT-' + Date.now(),
  event_type: raw.event_type || 'STATUS_UPDATE',
  timestamp: raw.timestamp || new Date().toISOString(),
  source: raw.source || 'erp_system',
  po_id: po.po_id || null,
  supplier_id: po.supplier_id || null,
  component_id: po.component_id || null,
  quantity: po.quantity != null ? Number(po.quantity) : null,
  unit_price: po.unit_price != null ? Number(po.unit_price) : null,
  expected_delivery: po.promised_delivery || po.expected_delivery || null,
  status: (po.status || '').toUpperCase(),
  notes: po.notes || ''
}}];

// ============================================================
// VALIDATE required fields
// ============================================================
const d = $json;
const required = { po_id: d.po_id, supplier_id: d.supplier_id, component_id: d.component_id, event_type: d.event_type };
const missing = Object.entries(required).filter(([k,v]) => !v).map(([k]) => k);
const validStatuses = ['OPEN','ORDERED','IN_TRANSIT','AT_RISK','DELAYED','RECEIVED','CANCELLED'];
const unknownStatus = d.status && !validStatuses.includes(d.status);

return [{ json: {
  ...d,
  is_valid: missing.length === 0,
  missing_fields: missing,
  unknown_status: unknownStatus,
  needs_agent: ['DELAYED', 'AT_RISK'].includes(d.status)
}}];

nodes.notes:
AGENT: ERP_EVENT_RECEIVER
Syncs normalized PO event to backend MongoDB.
Returns: { success, po_id, incident_id, agent_trigger_required }

parameters.jsCode:
const norm = $('[📦 [ERP RECEIVER] Normalize ERP Payload]').item.json;
const sync = $('[📦 [ERP RECEIVER] POST /integrations/erp/event]').item.json;
return [{ json: {
  event_id: 'AUD-' + Date.now(),
  timestamp: new Date().toISOString(),
  source: 'n8n',
  workflow: 'ERP_EVENT_SYNC',
  event_type: 'AGENT_TRIGGERED',
  incident_id: sync.incident_id || null,
  entity_type: 'PURCHASE_ORDER',
  entity_id: norm.po_id,
  action: 'TRIGGER_LLM_AGENT',
  status: 'SUCCESS',
  decision: 'AGENT_TRIGGERED',
  reason: 'PO status is ' + norm.status + ' — Groq LLM agent invoked',
  correlation_id: norm.correlation_id,
  retry_count: 0,
  input: { status: norm.status, event_type: norm.event_type },
  output: { incident_id: sync.incident_id }
}}];

// ============================================================
// EVALUATE DELIVERY COMMITMENTS
// ============================================================
const items = $input.all();
const today = new Date();
const out = [];

for (const item of items) {
  const po = item.json;
  if (!po.po_id || !po.promised_delivery) continue;

  const promised = new Date(po.promised_delivery);
  const expected = new Date(po.current_expected_delivery || po.promised_delivery);
  const diffDays = Math.round((expected - promised) / 86400000);
  const daysPastPromised = Math.round((today - promised) / 86400000);

  let status = 'ON_TRACK';
  if (['RECEIVED','DELIVERED','COMPLETED'].includes(po.status)) status = 'DELIVERED';
  else if (po.status === 'CANCELLED') status = 'CANCELLED';
  else if (diffDays > 0 && expected < today) status = 'BREACHED';
  else if (diffDays > 0 || (daysPastPromised > 0 && po.status === 'IN_TRANSIT')) status = 'AT_RISK';

  const severity = diffDays > 7 ? 'HIGH' : diffDays >= 3 ? 'MEDIUM' : 'LOW';
  const breachDateKey = (status === 'BREACHED' ? expected : today).toISOString().slice(0, 10);
  const idempotencyKey = po.po_id + '_' + severity + '_' + breachDateKey;
  const correlationId = 'CORR-MON-' + Date.now() + '-' + po.po_id;

  out.push({ json: {
    po_id: po.po_id,
    supplier_id: po.supplier_id,
    component_id: po.component_id,
    promised_date: po.promised_delivery,
    current_expected_date: po.current_expected_delivery || po.promised_delivery,
    delay_days: Math.max(diffDays, 0),
    days_past_promised: Math.max(daysPastPromised, 0),
    commitment_status: status,
    severity,
    idempotency_key: idempotencyKey,
    correlation_id: correlationId
  }});
}

return out.filter(i => i.json.commitment_status === 'BREACHED');

const sd = $getWorkflowStaticData('global');
if (!sd.processedBreaches) sd.processedBreaches = {};
const items = $input.all();
const fresh = [];
const now = Date.now();
// Prune keys older than 7 days
for (const [k, ts] of Object.entries(sd.processedBreaches)) {
  if (now - ts > 7 * 86400000) delete sd.processedBreaches[k];
}
for (const item of items) {
  const key = item.json.idempotency_key;
  if (!sd.processedBreaches[key]) {
    sd.processedBreaches[key] = now;
    fresh.push(item);
  }
}
return fresh;

const breach = $('[⏰ [MONITOR] Idempotency Check — Deduplicate Breaches]').item.json;
const incResp = $('[⏰ [MONITOR] POST /integrations/delivery-breach]').item.json;
return [{ json: {
  event_id: 'AUD-' + Date.now(),
  timestamp: new Date().toISOString(),
  source: 'n8n',
  workflow: 'DELIVERY_COMMITMENT_MONITOR',
  event_type: 'DELIVERY_COMMITMENT_BREACH',
  incident_id: incResp.incident_id || null,
  entity_type: 'PURCHASE_ORDER',
  entity_id: breach.po_id,
  action: 'TRIGGER_LLM_AGENT',
  status: 'SUCCESS',
  decision: 'DELIVERY_COMMITMENT_BREACH',
  reason: 'Delivery delayed by ' + breach.delay_days + ' days. Severity: ' + breach.severity,
  correlation_id: breach.correlation_id,
  retry_count: 0,
  input: { delay_days: breach.delay_days, severity: breach.severity },
  output: { incident_id: incResp.incident_id, agent_triggered: true }
}}];

const d = $json;
const required = { rfq_id: d.rfq_id, supplier_id: d.supplier_id, component_id: d.component_id, quantity: d.quantity, unit_price: d.unit_price, delivery_days: d.delivery_days };
const missing = Object.entries(required).filter(([k,v]) => v == null || v === '').map(([k]) => k);
const isValid = missing.length === 0;
const isPartial = missing.length > 0 && missing.length < 4;
return [{ json: {
  ...d,
  is_valid: isValid,
  is_partial: isPartial,
  missing_fields: missing
}}];

nodes.notes:
AGENT: MAIN_LLM_AGENT
Entry point for incident analysis. Called by ERP Receiver, Delivery Monitor, and Approval Agent.
Expects: { incident_id, correlation_id?, source? }

parameters.jsCode:
const ctx = $json;
const inbound = $('[🤖 [MAIN AGENT] Webhook — POST /webhook/agent/analyze-incident]').item.json;
const raw = inbound.body || inbound;
const incident = ctx.incident || {};
const context = ctx.context || {};
const inv = context.inventory || {};
const pos = (context.production_orders || []).map(p =>
  `  - ${p.production_id}: qty=${p.quantity}, need=${p.components_needed}, deadline=${p.deadline}, priority=${p.priority}, status=${p.status}`
).join('\n') || '  None';
const sups = (context.suppliers || []).map(s =>
  `  - ${s.supplier_id}: ${s.name}, reliability=${s.reliability_score}, quality=${s.quality_score}, lead_time=${s.lead_time_days}d, blacklisted=${s.blacklisted}, status=${s.status}`
).join('\n') || '  None';

const prompt = `You are the Supply Chain Disruption Control Agent — the primary AI orchestrator for the supply chain resilience system.

Your job:
1. Analyze the incident using all context provided.
2. Detect any data inconsistencies, anomalies, or conflicts.
3. Classify the issue and determine the appropriate recovery action.
4. Output a structured JSON decision.

===== INCIDENT =====
- ID: ${incident.incident_id}
- Type: ${incident.type}
- Severity: ${incident.severity}
- Affected Component: ${incident.affected_component}
- Affected PO: ${incident.affected_po}
- Supplier: ${incident.supplier_id}
- Status: ${incident.status}
- Delay Days: ${incident.delay_days || 0}
- Source: ${incident.source}

===== INVENTORY (Component: ${context.component_id}) =====
- Current Stock: ${inv.current_stock ?? 'MISSING'}
- Usable Stock: ${inv.usable_stock ?? 'MISSING'}
- Daily Usage: ${inv.daily_usage ?? 'MISSING'}
- Safety Stock: ${inv.safety_stock ?? 'MISSING'}
- Days of Supply: ${inv.days_of_supply ?? 'CALCULATED NEEDED'}

===== ACTIVE PRODUCTION ORDERS =====
${pos}

===== AVAILABLE SUPPLIERS =====
${sups}

===== ANOMALY DETECTION CHECKLIST =====
Check for all of the following:
- Negative stock values (current_stock < 0 or usable_stock < 0)
- Usable stock exceeding current stock
- Zero or null daily_usage with existing stock (orphaned inventory)
- Supplier with null or missing reliability_score
- Blacklisted supplier with active open POs
- PO with no promised_delivery date
- PO referencing a supplier not in the system
- Production order referencing a component with no inventory record
- Production deadline already past but status is ON_TRACK
- Incident with no affected_component
- Duplicate incidents for same PO

===== ROUTING RULES =====
- APPROVE_AUTONOMOUS: Recovery cost <= $${$env.AUTONOMOUS_APPROVAL_LIMIT_USD || 50000} AND low risk AND no anomalies
- NEEDS_HUMAN_APPROVAL: Recovery cost > $${$env.AUTONOMOUS_APPROVAL_LIMIT_USD || 50000} OR high risk
- DATA_INCONSISTENCY: Any anomalies detected from checklist above
- ESCALATE_NO_RESOLUTION: Cannot determine recovery path

===== RESPONSE FORMAT =====
Respond with ONLY valid JSON (no markdown, no explanation outside JSON):
{
  "decision": "APPROVE_AUTONOMOUS" | "NEEDS_HUMAN_APPROVAL" | "DATA_INCONSISTENCY" | "ESCALATE_NO_RESOLUTION",
  "routing_target": "EXECUTE_AUTONOMOUS" | "APPROVAL_AGENT" | "ERROR_HANDLER" | "OPS_ESCALATION",
  "incident_type": "SUPPLIER_DELAY" | "DELIVERY_BREACH" | "INVENTORY_CRITICAL" | "DATA_INCONSISTENCY" | "UNKNOWN",
  "anomalies_detected": [],
  "recommended_action": "<concise action description>",
  "reasoning": "<2-3 sentence human-readable summary for audit log>",
  "estimated_impact": "<impact description>",
  "estimated_cost_usd": <number or null>,
  "requires_approval": <true|false>
}`;

return [{ json: {
  incident_id: ctx.incident_id,
  correlation_id: raw.correlation_id || ('CORR-AGT-' + Date.now()),
  state: ctx.state,
  prompt,
  incident,
  context
}}];

const rawText = $json.text || $json.response || '';
const promptCtx = $('[🤖 [MAIN AGENT] Build LLM Prompt with Anomaly Detection]').item.json;
const incidentId = promptCtx.incident_id;
const correlationId = promptCtx.correlation_id;

let parsed = {
  decision: 'NEEDS_HUMAN_APPROVAL',
  routing_target: 'APPROVAL_AGENT',
  incident_type: 'UNKNOWN',
  anomalies_detected: [],
  recommended_action: 'Manual review required — Groq parse error',
  reasoning: rawText.slice(0, 300),
  estimated_impact: 'Unknown',
  estimated_cost_usd: null,
  requires_approval: true
};

try {
  const match = rawText.match(/\{[\s\S]*?\}/);
  if (match) {
    const candidate = JSON.parse(match[0]);
    parsed = { ...parsed, ...candidate };
  }
} catch(e) {
  // Keyword fallback
  if (rawText.toUpperCase().includes('APPROVE_AUTONOMOUS')) parsed.decision = 'APPROVE_AUTONOMOUS';
  if (rawText.toUpperCase().includes('DATA_INCONSISTENCY')) parsed.decision = 'DATA_INCONSISTENCY';
}

const validDecisions = ['APPROVE_AUTONOMOUS','NEEDS_HUMAN_APPROVAL','DATA_INCONSISTENCY','ESCALATE_NO_RESOLUTION'];
if (!validDecisions.includes(parsed.decision)) parsed.decision = 'NEEDS_HUMAN_APPROVAL';

// Set routing_target based on decision if not set by LLM
if (!parsed.routing_target || parsed.routing_target === 'APPROVAL_AGENT') {
  if (parsed.decision === 'APPROVE_AUTONOMOUS') parsed.routing_target = 'EXECUTE_AUTONOMOUS';
  else if (parsed.decision === 'DATA_INCONSISTENCY') parsed.routing_target = 'ERROR_HANDLER';
  else if (parsed.decision === 'ESCALATE_NO_RESOLUTION') parsed.routing_target = 'OPS_ESCALATION';
  else parsed.routing_target = 'APPROVAL_AGENT';
}

return [{ json: {
  incident_id: incidentId,
  correlation_id: correlationId,
  decision: parsed.decision,
  routing_target: parsed.routing_target,
  incident_type: parsed.incident_type,
  anomalies_detected: parsed.anomalies_detected || [],
  recommended_action: parsed.recommended_action,
  reasoning: parsed.reasoning,
  estimated_impact: parsed.estimated_impact,
  estimated_cost_usd: parsed.estimated_cost_usd,
  requires_approval: parsed.requires_approval,
  groq_raw: rawText
}}];

const dec = $json;
const ctx = $('[🤖 [MAIN AGENT] POST /agent/trigger — Fetch Incident Context]').item.json;
const cfg = $('[🤖 [MAIN AGENT] GET /api/v1/config/n8n — Fetch Backend Config]').item.json;
const incident = (ctx.incident || ctx.context && ctx.context.incident || {});
const inv = (ctx.context && ctx.context.inventory) || {};
const suppliers = (ctx.context && ctx.context.suppliers) || [];

const altSuppliers = suppliers
  .filter(s => !s.blacklisted && s.status !== 'INACTIVE')
  .map(s => s.supplier_id + ' (' + s.name + ', lead_time=' + s.lead_time_days + 'd, reliability=' + s.reliability_score + ')')
  .join(', ') || 'None available';

const approvalLimit = cfg.autonomous_approval_limit_usd || $env.AUTONOMOUS_APPROVAL_LIMIT_USD || 50000;

const prompt = `You are the Supply Chain Recovery Planner for the incident management system.

Based on the primary LLM analysis and full incident context below, generate a structured recovery action plan.

===== PRIMARY ANALYSIS RESULT =====
- Incident ID: ${dec.incident_id}
- Decision: ${dec.decision}
- Routing Target: ${dec.routing_target}
- Incident Type: ${dec.incident_type}
- Recommended Action: ${dec.recommended_action}
- Reasoning: ${dec.reasoning}
- Estimated Impact: ${dec.estimated_impact}
- Estimated Cost (USD): ${dec.estimated_cost_usd ?? 'Unknown'}
- Autonomous Approval Limit: $${approvalLimit}
- Anomalies Detected: ${JSON.stringify(dec.anomalies_detected || [])}

===== PRODUCT / INVENTORY CONTEXT =====
- Component ID: ${incident.affected_component || 'Unknown'}
- Current Stock: ${inv.current_stock ?? 'Unknown'}
- Days of Supply Remaining: ${inv.days_of_supply ?? 'Unknown'}
- Delay Days: ${incident.delay_days || 0}
- Financial Loss Risk (USD): ${dec.estimated_cost_usd ?? 'Unknown'}

===== ALTERNATIVE SUPPLIERS =====
${altSuppliers}

===== INSTRUCTIONS =====
Analyze the situation and output ONLY the following strict JSON (no markdown, no explanation):
{
  "action_summary": "<1-2 sentence plain-English recovery action>",
  "logistics_reroute": <true if rerouting logistics is needed | false>,
  "expedite_recommended": <true if expedited shipping should be used | false>,
  "estimated_recovery_hours": <integer estimate of hours to recover supply>,
  "risk_mitigation_steps": ["<step 1>", "<step 2>", "<step 3>"]
}`;

return [{ json: {
  incident_id: dec.incident_id,
  correlation_id: dec.correlation_id,
  decision: dec.decision,
  routing_target: dec.routing_target,
  incident_type: dec.incident_type,
  anomalies_detected: dec.anomalies_detected,
  recommended_action: dec.recommended_action,
  reasoning: dec.reasoning,
  estimated_impact: dec.estimated_impact,
  estimated_cost_usd: dec.estimated_cost_usd,
  requires_approval: dec.requires_approval,
  groq_raw: dec.groq_raw,
  post_analysis_prompt: prompt,
  cfg_notify_from_email: cfg.notify_from_email || $env.NOTIFY_FROM_EMAIL || '',
  cfg_approval_notify_email: cfg.approval_notify_email || $env.APPROVAL_NOTIFY_EMAIL || '',
  cfg_ops_alert_email: cfg.ops_alert_email || $env.OPS_ALERT_EMAIL || '',
  cfg_approval_limit: cfg.autonomous_approval_limit_usd || approvalLimit,
  cfg_llm_model: cfg.llm_config && cfg.llm_config.model || $env.GROQ_MODEL || 'llama-3.3-70b-versatile'
}}];

const rawText = $json.text || $json.response || '';
const upstream = $('[🤖 [MAIN AGENT] Build Groq Post-Analysis Prompt]').item.json;

let actionPlan = {
  action_summary: 'Manual recovery review recommended',
  logistics_reroute: false,
  expedite_recommended: false,
  estimated_recovery_hours: 72,
  risk_mitigation_steps: ['Escalate to ops team', 'Review supplier alternatives', 'Monitor stock levels']
};

try {
  // Try to extract JSON block from LLM response
  const match = rawText.match(/\{[\s\S]*?\}/);
  if (match) {
    const candidate = JSON.parse(match[0]);
    // Validate required fields exist
    if (candidate.action_summary) actionPlan = { ...actionPlan, ...candidate };
  }
} catch(e) {
  // Keep safe defaults on parse failure — never throw
}

// Ensure array type
if (!Array.isArray(actionPlan.risk_mitigation_steps)) {
  actionPlan.risk_mitigation_steps = [String(actionPlan.risk_mitigation_steps || 'Review manually')];
}

return [{ json: {
  // Pass through all decision fields from primary LLM stage
  incident_id: upstream.incident_id,
  correlation_id: upstream.correlation_id,
  decision: upstream.decision,
  routing_target: upstream.routing_target,
  incident_type: upstream.incident_type,
  anomalies_detected: upstream.anomalies_detected,
  recommended_action: upstream.recommended_action,
  reasoning: upstream.reasoning,
  estimated_impact: upstream.estimated_impact,
  estimated_cost_usd: upstream.estimated_cost_usd,
  requires_approval: upstream.requires_approval,
  groq_raw: upstream.groq_raw,
  // Dynamic config values (surfaced for downstream email/approval nodes)
  cfg_notify_from_email: upstream.cfg_notify_from_email,
  cfg_approval_notify_email: upstream.cfg_approval_notify_email,
  cfg_ops_alert_email: upstream.cfg_ops_alert_email,
  cfg_approval_limit: upstream.cfg_approval_limit,
  cfg_llm_model: upstream.cfg_llm_model,
  // Post-analysis action plan
  action_plan: {
    action_summary: actionPlan.action_summary,
    logistics_reroute: Boolean(actionPlan.logistics_reroute),
    expedite_recommended: Boolean(actionPlan.expedite_recommended),
    estimated_recovery_hours: Number(actionPlan.estimated_recovery_hours) || 72,
    risk_mitigation_steps: actionPlan.risk_mitigation_steps
  },
  post_analysis_raw: rawText
}}];

const b = $json.body || $json;
const base = $env.N8N_BASE_URL;
const approver = encodeURIComponent($env.APPROVAL_APPROVER_NAME || 'procurement_manager');
const correlationId = encodeURIComponent(b.correlation_id || '');
const approveUrl = base + '/webhook/approval-decision/approve?incident_id=' + encodeURIComponent(b.incident_id) + '&plan_id=' + encodeURIComponent(b.plan_id || '') + '&approver=' + approver + '&correlation_id=' + correlationId;
const rejectUrl = base + '/webhook/approval-decision/reject?incident_id=' + encodeURIComponent(b.incident_id) + '&plan_id=' + encodeURIComponent(b.plan_id || '') + '&approver=' + approver + '&reason=' + encodeURIComponent('Cost exceeds budget') + '&correlation_id=' + correlationId;
const limit = $env.AUTONOMOUS_APPROVAL_LIMIT_USD || 50000;
const text = `SUPPLY CHAIN DISRUPTION — APPROVAL REQUIRED\n\nIncident ID: ${b.incident_id}\nCorrelation ID: ${b.correlation_id}\n\nRequired Action: ${b.required_action || 'Review recovery plan'}\nReason: ${b.reason || 'Cost exceeds $' + limit}\n\nEstimated Cost: ${b.estimated_cost || 'Unknown'} ${b.currency || 'USD'}\nApproval Threshold: $${limit}\nRisk Level: ${b.risk || 'Unknown'}\n\n✅ APPROVE: ${approveUrl}\n\n❌ REJECT: ${rejectUrl}\n\nThis approval request will expire in 24 hours.`;
return [{ json: {
  incident_id: b.incident_id,
  plan_id: b.plan_id,
  estimated_cost: b.estimated_cost,
  risk: b.risk,
  correlation_id: b.correlation_id,
  approve_url: approveUrl,
  reject_url: rejectUrl,
  email_text: text
}}];

const q = $json.query || {};
const params = $json.params || {};
const decision = (params.decision || '').toLowerCase();
return [{ json: {
  decision,
  incident_id: q.incident_id,
  plan_id: q.plan_id,
  approver: q.approver || 'procurement_manager',
  reason: q.reason || null,
  correlation_id: q.correlation_id || null,
  is_valid_decision: ['approve','reject'].includes(decision)
}}];

const b = $json.body || $json;
const urgency = (b.urgency || 'MEDIUM').toUpperCase();
const type = b.notification_type || 'GENERAL';
return [{ json: {
  notification_id: 'NOTIF-' + Date.now(),
  notification_type: type,
  urgency,
  incident_id: b.incident_id || null,
  message: b.message || 'Supply chain notification',
  correlation_id: b.correlation_id || null,
  send_email: ['CRITICAL','HIGH'].includes(urgency),
  details: b
}}];

const err = $json;
const execErr = err.execution && err.execution.error ? err.execution.error : {};
const msg = (execErr.message || '').toLowerCase();
const nodeName = err.node && err.node.name ? err.node.name : 'UNKNOWN_NODE';
const workflowName = err.workflow && err.workflow.name ? err.workflow.name : 'UNKNOWN_WORKFLOW';

let errorType = 'UNKNOWN';
let retryable = false;
let urgency = 'MEDIUM';

if (msg.includes('401') || msg.includes('403') || msg.includes('unauthorized') || msg.includes('forbidden')) {
  errorType = 'AUTH_FAILURE';
  retryable = false;
  urgency = 'CRITICAL';
} else if (msg.includes('timeout') || msg.includes('econnreset') || msg.includes('etimedout')) {
  errorType = 'TIMEOUT';
  retryable = true;
  urgency = 'HIGH';
} else if (msg.includes('400') || msg.includes('validation')) {
  errorType = 'VALIDATION_FAILURE';
  retryable = false;
  urgency = 'MEDIUM';
} else if (msg.includes('404')) {
  errorType = 'NOT_FOUND';
  retryable = false;
  urgency = 'MEDIUM';
} else if (msg.includes('5') || msg.includes('503') || msg.includes('502') || msg.includes('500')) {
  errorType = 'HTTP_5XX';
  retryable = true;
  urgency = 'HIGH';
} else if (msg.includes('groq') || msg.includes('llm')) {
  errorType = 'LLM_FAILURE';
  retryable = true;
  urgency = 'HIGH';
}

return [{ json: {
  error_id: 'ERR-' + Date.now(),
  correlation_id: 'CORR-ERR-' + Date.now(),
  error_type: errorType,
  retryable,
  urgency,
  workflow_name: workflowName,
  node_name: nodeName,
  error_message: execErr.message || 'Unknown error',
  execution_id: err.execution && err.execution.id ? err.execution.id : null
}}];

nodes.notes:
AGENT: REPORT_GENERATOR_AGENT
On-demand audit trail report generation.
Params: { format: 'csv'|'pdf'|'both', incident_id?: string }

parameters.jsCode:
const b = $json.body || $json;
const format = (b.format || 'both').toLowerCase();
const validFormats = ['csv','pdf','both'];
return [{ json: {
  report_id: 'RPT-' + Date.now(),
  correlation_id: 'CORR-RPT-' + Date.now(),
  format: validFormats.includes(format) ? format : 'both',
  incident_id: b.incident_id || null,
  generate_csv: format === 'csv' || format === 'both',
  generate_pdf: format === 'pdf' || format === 'both',
  requested_at: new Date().toISOString()
}}];

const p = $json;
const base = $env.BACKEND_URL;
const suffix = p.incident_id ? '?incident_id=' + encodeURIComponent(p.incident_id) : '';
